#include <stdio.h>
#include <stdlib.h>
struct Node{int value;struct Node*next;};
static void destroy(struct Node*p){while(p){struct Node*next=p->next;free(p);p=next;}}
int main(void) {
    int n;if(scanf("%d",&n)!=1||n<0||n>20)return 1;
    struct Node*head=NULL;
    for(int i=0;i<n;i++){int x;if(scanf("%d",&x)!=1){destroy(head);return 1;}struct Node*p=malloc(sizeof*p);if(!p){destroy(head);return 1;}p->value=x;p->next=head;head=p;}
    int sum=0;for(struct Node*p=head;p;p=p->next)sum+=p->value;
    printf("%d\n",sum);destroy(head);
    return 0;
}

