struct Node{int value;struct Node*next;};
static void destroy(struct Node*p){while(p){struct Node*n=p->next;free(p);p=n;}}
int main(void) {
    struct Node*head=NULL,**tail=&head;int target;
    for(int i=0;i<3;i++){int x;if(scanf("%d",&x)!=1){destroy(head);return 1;}struct Node*p=malloc(sizeof*p);if(!p){destroy(head);return 1;}p->value=x;p->next=NULL;*tail=p;tail=&p->next;}
    if(scanf("%d",&target)!=1){destroy(head);return 1;}
    struct Node**link=&head;while(*link&&(*link)->value!=target)link=&(*link)->next;
    if(*link){struct Node*old=*link;*link=old->next;free(old);}
    int first=1;for(struct Node*p=head;p;p=p->next){printf("%s%d",first?"":" ",p->value);first=0;}putchar('\n');destroy(head);
    return 0;
}

